Here's a basic outline of the code structure:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <SDL2/SDL_mixer.h>

// Define constants for the game
#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define SNAKE_SIZE 20
#define FOOD_SIZE 20
#define FPS 60
#define FOOD_SPAWN_RATE 10 // spawn food every 10 seconds

// Define structures for the game objects
typedef struct Snake {
    int x, y;
    SDL_Rect rect;
    int length;
    SDL_Texture *texture;
} Snake;

typedef struct Food {
    int x, y;
    SDL_Rect rect;
    SDL_Texture *texture;
} Food;

// Define function prototypes
void initSDL(SDL_Window **window, SDL_Renderer **renderer);
void closeSDL(SDL_Window *window, SDL_Renderer *renderer);
void loadTextures(SDL_Renderer *renderer, SDL_Texture **snakeTexture, SDL_Texture **foodTexture, SDL_Texture **backgroundTexture);
void renderScene(SDL_Renderer *renderer, Snake *snake, Food *food, int score);
void handleInput(Snake *snake);
void updateGame(Snake *snake, Food *food, int *score, int *gameOver);
void spawnFood(Food *food, SDL_Renderer *renderer);
void freeGameMemory(Snake *snake, Food *food);

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;
    Snake snake;
    Food food;
    int score = 0;
    int gameOver = 0;
    Uint32 startTick, endTick;
    Uint32 interval;

    // Initialize SDL
    initSDL(&window, &renderer);

    // Load textures
    SDL_Texture *snakeTexture, *foodTexture, *backgroundTexture;
    loadTextures(renderer, &snakeTexture, &foodTexture, &backgroundTexture);

    // Initialize game objects
    snake.x = SCREEN_WIDTH / 2;
    snake.y = SCREEN_HEIGHT / 2;
    snake.rect.w = snake.rect.h = SNAKE_SIZE;
    snake.rect.x = snake.x - snake.rect.w / 2;
    snake.rect.y = snake.y - snake.rect.h / 2;
    snake.length = 1;
    snake.texture = snakeTexture;

    food.x = 0;
    food.y = 0;
    food.rect.w = food.rect.h = FOOD_SIZE;
    food.rect.x = food.x - food.rect.w / 2;
    food.rect.y = food.y - food.rect.h / 2;
    food.texture = foodTexture;

    // Main game loop
    while (!gameOver) {
        startTick = SDL_GetTicks();

        // Handle input events
        handleInput(&snake);

        // Update game state
        updateGame(&snake, &food, &score, &gameOver);

        // Render the scene
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, backgroundTexture, NULL, NULL);
        renderScene(renderer, &snake, &food, score);
        SDL_RenderPresent(renderer);

        // Spawn food
        if (SDL_GetTicks() - food.spawnTick > FOOD_SPAWN_RATE * 1000) {
            spawnFood(&food, renderer);
        }

        // Cap the framerate
        endTick = SDL_GetTicks();
        interval = 1000 / FPS - (endTick - startTick);
        if (interval > 0) {
            SDL_Delay(interval);
        }
    }

    // Free game memory
    freeGameMemory(&snake, &food);

    // Close SDL
    closeSDL(window, renderer);

    return 0;
}
```

